"use client";

import { motion } from "motion/react";

export function SplitRevealTailwind({ text = "Every pixel earns its place." }) {
  return (
    <span aria-label={text} className="text-4xl font-semibold tracking-tight text-zinc-100">
      {text.split(" ").map((w, i) => (
        <span key={i} aria-hidden className="mr-[0.25em] inline-block overflow-hidden pb-[0.08em] align-bottom">
          <motion.span
            className="inline-block"
            initial={{ y: "110%" }}
            animate={{ y: 0 }}
            transition={{ delay: i * 0.1, duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
          >
            {w}
          </motion.span>
        </span>
      ))}
    </span>
  );
}
